  "devdoc": {
    "events": {
      "AdminChanged(address,address)": {
        "details": "Emitted when the admin account has changed."
      },
      "BeaconUpgraded(address)": {
        "details": "Emitted when the beacon is changed."
      },
      "Initialized(uint8)": {
        "details": "Triggered when the contract has been initialized or reinitialized."
      },
      "Upgraded(address)": {
        "details": "Emitted when the implementation is upgraded."
      }
    },
    "kind": "dev",
    "methods": {
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor",
        "params": {
          "_factory": "The factory that approves upgrade targets. Must have        code: the value cannot be corrected after this point.",
          "_protocolSafe": "The protocol safe this deploy expects the factory to        name. Not proof of ownership: what binds this implementation to        the protocol is the protocol safe's `setImplementation`."
        }
      },
      "initialize(address,bytes)": {
        "details": "Called by the factory, in the same call that deployed this proxy,      with the Safe the factory recorded. `params` is      `abi.encode(string version, string json)` to publish the first      document, or empty."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "setManifest(string,string)": {
        "details": "The major is checked here, not by the reader. A document whose major      is not `VERSION()` is a document this module cannot be read      alongside, so it is refused before it can be stored.      A version that is already history is refused: history is what a      reader pinned to a release gets, and silently rewriting it would      change an answer that was already given. The live version may be      rewritten, which is how a CID is corrected within the release that      has not yet been pinned; moving to a new release uses a new version."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "stateVariables": {
      "FACTORY": {
        "details": "The factory whose approved set decides what this module may upgrade      to. Immutable: no storage write can change it, and it is the same      answer for every proxy over this implementation."
      },
      "currentJson": {
        "details": "The live document and the version written beside it. One write, two      answers, so a reader cannot be handed a version from one publish and      a document from another."
      }
    },
    "version": 1
  },
